contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs a Put from this contract to c with amount `amount` and a chosen unlockTime `ut`.
    // It then checks that if the call did not revert, the Acc balance for this caller increased by amount
    // and address(c).balance increased by amount. If the call reverted, no state change is required.
    function run(uint ut, uint amount) public payable {
        require(address(this).balance >= amount);
        // read balance and contract balance before
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeCbalance = address(c).balance;

        bool reverted;
        // call Put sending `amount` wei
        try c.Put{value: amount}(ut) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterCbalance = address(c).balance;

        // If the call succeeded, then the holder balance must have increased by exactly amount
        // and the contract's ETH balance must have increased by amount. If it reverted, we cannot
        // assume any changes, so assert nothing about state change in that case. This is a general
        // rule about successful Put.
        assert(reverted || (afterHolderBalance == beforeHolderBalance + amount && afterCbalance == beforeCbalance + amount));
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

