contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to perform a Collect of amount am after ensuring Acc[msg.sender] has at least am and unlockTime passed.
    // We supply funds to c via Put beforehand so the Collect call can succeed in the intended case.
    function run(uint storedUnlock, uint initialDeposit, uint am) public payable {
        // We will send initialDeposit to c in a Put call. Require we have enough balance to do that.
        require(address(this).balance >= initialDeposit);

        // Record balances before setup
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeCbalance = address(c).balance;

        // Deposit initialDeposit into c so that Acc[this].balance increases by that amount (if Put succeeds).
        bool putReverted;
        try c.Put{value: initialDeposit}(storedUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read state after Put attempt
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));
        uint midCbalance = address(c).balance;

        // We attempt Collect of am. We require nothing about whether it should succeed here; capture revert flag.
        bool collectReverted;
        try c.Collect(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read state after Collect attempt
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));
        uint afterCbalance = address(c).balance;

        // If Collect succeeded then holder balance must have decreased by exactly am and c's Ether balance decreased by exactly am.
        assert(collectReverted || (midHolderBalance >= am && afterHolderBalance == midHolderBalance - am && midCbalance >= am && afterCbalance == midCbalance - am));
    }

    // accept Ether when Put or Collect send to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // storedUnlock: unlockTime to use when funding via Put
    // deposit: amount of wei to send in Put
    // am: amount to attempt to Collect
    function run(uint storedUnlock, uint deposit, uint am) public payable {
        // ensure this test contract has enough Ether to send deposit
        require(address(this).balance >= deposit);

        // Read holder info before any interaction
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // Try to Put deposit into c (may revert)
        bool putReverted;
        try c.Put{value: deposit}(storedUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read holder info after Put attempt
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Now attempt Collect(am) and record whether it reverted
        bool collectReverted;
        try c.Collect(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // After Collect, read holder info
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // If Collect did not revert then the conditions required by Collect's body must have held
        // i.e., at the time of the Collect call: holder balance >= MinSum, holder balance >= am, and block.timestamp > unlockTime.
        // We observe holder balance and unlockTime immediately before the Collect call as midBalance/midUnlock.
        uint Min = c.MinSum();

        assert(collectReverted || (midBalance >= Min && midBalance >= am && block.timestamp > midUnlock));
    }

    // receive to accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // storedUnlock: unlockTime used when funding via Put
    // deposit: wei to send in Put
    // am: amount to attempt to Collect
    function run(uint storedUnlock, uint deposit, uint am) public payable {
        require(address(this).balance >= deposit);

        // read holder state before any interaction
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // attempt to Put deposit (may revert)
        bool putReverted;
        try c.Put{value: deposit}(storedUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read holder state after Put attempt but before Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // attempt Collect(am)
        bool collectReverted;
        try c.Collect(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read holder state after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
        // If Collect did not revert then (1) the recorded balance for this caller did not increase
        // (it must be <= the balance observed immediately before Collect), and (2) the contract's
        // Ether balance did not increase as a result of Collect (Collect can only send out ETH).
        // We observed midBalance/midCbal immediately before the Collect call and afterBalance/afterCbal after.
        assert(collectReverted || (afterBalance <= midBalance && afterCbal <= midCbal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run drives a Put call and then checks that the balance recorded in Acc[msg.sender]
    // and the contract's Ether balance increased by the sent amount when Put succeeds.
    function run(uint _unlockTime, uint amount) public payable {
        // ensure this contract has enough balance to send amount to c
        require(address(this).balance >= amount);

        // read before-values via public getters
        // Acc is public mapping; its getter returns (unlockTime, balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // call Put with value amount and catch revert
        bool reverted = false;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call did not revert then recorded balance must increase by amount
        // and contract ETH balance must increase by amount. If it reverted, no guarantee.
        assert(reverted || (afterBal == beforeBal + amount && afterContractBal == beforeContractBal + amount));
    }

    // Allow receiving Ether so the test can be funded externally before run
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive a Put to ensure there is some balance, then attempt Collect for some amount.
    // Parameters:
    //   putUnlock: unlock time used when putting funds (can be 0 to set to block.timestamp)
    //   putAmount: Ether amount to send with Put (must be funded to this contract)
    //   collectAmount: amount to attempt to Collect
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // ensure test contract can send the intended putAmount to c
        require(address(this).balance >= putAmount);

        // read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put to add funds (may revert). We catch revert to observe Collect behavior only when Put succeeded.
        bool putReverted = false;
        try c.Put{value: putAmount}(putUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read middle-values after Put attempt
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect for collectAmount and observe whether it reverts.
        bool collectReverted = false;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then the recorded balance for this address decreased by collectAmount
        // and the contract's Ether balance decreased by at least collectAmount (sent out).
        // If Collect reverted then we make no claim. Also if Put reverted and thus midBal did not increase,
        // Collect may still revert; our assertion allows that by requiring collectReverted OR the relation.
        assert(collectReverted || (midBal >= collectAmount && afterBal + collectAmount == midBal && midContractBal >= collectAmount && afterContractBal + collectAmount <= midContractBal));
    }

    // Allow this test contract to receive Ether to fund Put
    receive() external payable {}
}
